START TRANSACTION;
CREATE TABLE support_pass_definitions(pass_code VARCHAR(64) NOT NULL,display_name VARCHAR(191) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(pass_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO support_pass_definitions(pass_code,display_name,active) VALUES('contribution','공헌패스',TRUE) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),active=TRUE;
CREATE TABLE player_support_passes(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,player_id BIGINT UNSIGNED NOT NULL,pass_code VARCHAR(64) NOT NULL,entitlement_kind ENUM('permanent','dated') NOT NULL,end_date DATE NULL,status ENUM('active','revoked','expired') NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_operation_id BIGINT UNSIGNED NOT NULL,updated_operation_id BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_player_support_pass(player_id,pass_code),CONSTRAINT fk_support_pass_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT,CONSTRAINT fk_support_pass_definition FOREIGN KEY(pass_code) REFERENCES support_pass_definitions(pass_code) ON DELETE RESTRICT,CONSTRAINT fk_support_pass_created_operation FOREIGN KEY(created_operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_support_pass_updated_operation FOREIGN KEY(updated_operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT chk_support_pass_end CHECK((entitlement_kind='permanent' AND end_date IS NULL) OR (entitlement_kind='dated' AND end_date IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE support_pass_change_events(operation_id BIGINT UNSIGNED NOT NULL,pass_id BIGINT UNSIGNED NULL,player_id BIGINT UNSIGNED NOT NULL,pass_code VARCHAR(64) NOT NULL,action_code ENUM('add','delete') NOT NULL,previous_status VARCHAR(32) NULL,previous_kind VARCHAR(32) NULL,previous_end_date DATE NULL,next_status VARCHAR(32) NOT NULL,next_kind VARCHAR(32) NULL,next_end_date DATE NULL,changed BOOLEAN NOT NULL,created_at DATETIME(3) NOT NULL,PRIMARY KEY(operation_id),CONSTRAINT fk_support_pass_change_operation FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_support_pass_change_pass FOREIGN KEY(pass_id) REFERENCES player_support_passes(id) ON DELETE RESTRICT,CONSTRAINT fk_support_pass_change_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('CONTRIBUTION_PASS_REGISTRY','contribution_pass_registry','VERIFIED_USER','SHADOW',TRUE,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),rollout_state=VALUES(rollout_state),enabled=TRUE,version=version+1;
INSERT INTO command_aliases(command_text,command_code,active) VALUES('/공헌패스추가','CONTRIBUTION_PASS_REGISTRY',TRUE),('/공헌패스삭제','CONTRIBUTION_PASS_REGISTRY',TRUE) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=TRUE;
COMMIT;
